// ui-general · кейсы ui-04, ui-11 (.qa/tests/ui-general/) — כשל טעינה (500) בשאר המסכים; «הזמנות» — в orders/orders-list.spec.ts
// #59d59e6f (2026-10-04): все сообщения «… נסה שוב.» в ед. ч., «נסו שוב» нигде (экраны + загруженные JS-бандлы).
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const screens = [
  { name: 'קטלוג', route: '**/rest/v1/products?*', url: '/catalog', error: 'אירעה שגיאה בטעינת המוצרים. נסה שוב.', ok: /^הכל\s*\d+$/, tags: '#6a677c6b #59d59e6f' },
  { name: 'לקוחות', route: '**/rest/v1/customers?*', url: '/customers', error: 'אירעה שגיאה בטעינת הלקוחות. נסה שוב.', ok: null, tags: '#6a677c6b #59d59e6f' },
  { name: 'קבוצות מוצרים', route: '**/rest/v1/product_groups?*', url: '/pricing/groups', error: 'אירעה שגיאה בטעינת קבוצות המוצרים. נסה שוב.', ok: null, tags: '#6a677c6b #59d59e6f' },
  { name: 'קטגוריות', route: '**/rest/v1/categories?*', url: '/catalog/categories', error: 'אירעה שגיאה בטעינת הקטגוריות. נסה שוב.', ok: null, tags: '#59d59e6f' },
  // /team: свой профиль (id=eq.…) не трогаем — только список сотрудников (role=neq.customer)
  { name: 'צוות והרשאות', route: /\/rest\/v1\/profiles\?.*role=neq\.customer/, url: '/team', error: 'אירעה שגיאה בטעינת הצוות. נסה שוב.', ok: null, tags: '#59d59e6f' },
  { name: 'לוח בקרה', route: '**/rest/v1/rpc/dashboard_metrics*', url: '/dashboard', error: 'שגיאה בטעינת הנתונים', ok: null, tags: '#6a677c6b' },
  { name: 'משלוחים', route: '**/rest/v1/rpc/driver_orders*', url: '/delivery', error: 'טעינת רשימת החלוקה נכשלה. נסה שוב.', ok: null, tags: '#6a677c6b' },
];

test.describe('ui-general — כשל טעינה (500)', () => {
  for (const s of screens) {
    test(`${s.name}: שגיאה עם «נסה שוב» תוך שניות, בלי מצב ריק שקרי ${s.tags} @desktop @prod-safe`, async ({ page }) => {
      await page.route(s.route, (r) => r.fulfill({ status: 500, contentType: 'application/json', body: '{"message":"QA simulated"}' }));
      const t0 = Date.now();
      await page.goto(s.url);
      // время «≈2 с, не ~20 с» — требование #6a677c6b; для экранов только из #59d59e6f проверяем лишь текст
      const timed = s.tags.includes('#6a677c6b');
      await expect(page.getByText(s.error)).toBeVisible({ timeout: timed ? 10_000 : 30_000 });
      if (timed) expect(Date.now() - t0).toBeLessThan(10_000);
      const retry = page.getByRole('button', { name: 'נסה שוב' });
      await expect(retry).toBeVisible();
      await expect(page.getByText(/נסו שוב/)).toHaveCount(0);
      if (s.ok) await expect(page.getByRole('button', { name: s.ok })).toHaveCount(0);
      await page.unroute(s.route);
      await retry.click();
      await expect(page.getByText(s.error)).toHaveCount(0, { timeout: 20_000 });
      if (s.ok) await expect(page.getByRole('button', { name: s.ok })).toBeVisible({ timeout: 20_000 });
    });
  }
});

test.describe('ui-general — «נסה שוב» בלשון יחיד (#59d59e6f)', () => {
  test('בקבצי ה-JS שנטענים במסכי הניהול אין «נסו שוב» #59d59e6f @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    const bundles = new Map<string, Promise<string>>();
    page.on('response', (r) => {
      const u = r.url();
      if (/\.js(\?|$)/.test(u) && !bundles.has(u)) bundles.set(u, r.text().catch(() => ''));
    });
    for (const url of ['/catalog', '/customers', '/pricing/groups', '/orders', '/catalog/categories', '/team', '/warehouse/picking']) {
      await page.goto(url);
      await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible({ timeout: 20_000 });
    }
    expect(bundles.size, 'JS-бандлы приложения загружены').toBeGreaterThan(0);
    const withPlural: string[] = [];
    for (const [u, body] of bundles) if ((await body).includes('נסו שוב')) withPlural.push(u);
    expect(withPlural, '«נסו שוב» не должно быть ни в одном бандле').toEqual([]);
  });
});
